fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        let mut i: i32 = 0;
        while i < 6 {
            let r: i32 = 40 + i * 18;
            host::display::state_set(8 + i * 4, (cx + r) * 16);
            host::display::state_set(9 + i * 4, cy * 16);
            host::display::state_set(10 + i * 4, 0);
            host::display::state_set(11 + i * 4, r * 16 / 11);
            i = i + 1;
        }
    }
    host::display::clear(0x000008);
    host::display::fill_rect(cx - 10, cy - 10, 20, 20, 0xffd830);
    let mut i: i32 = 0;
    while i < 6 {
        let b: i32 = 8 + i * 4;
        let mut x: i32 = host::display::state_get(b);
        let mut y: i32 = host::display::state_get(b + 1);
        let mut vx: i32 = host::display::state_get(b + 2);
        let mut vy: i32 = host::display::state_get(b + 3);
        vx = vx + (cx * 16 - x) / 128;
        vy = vy + (cy * 16 - y) / 128;
        x = x + vx;
        y = y + vy;
        host::display::state_set(b, x);
        host::display::state_set(b + 1, y);
        host::display::state_set(b + 2, vx);
        host::display::state_set(b + 3, vy);
        let g: i32 = 120 + i * 22;
        host::display::fill_rect(x / 16 - 3, y / 16 - 3, 6, 6, g * 256 + 255);
        i = i + 1;
    }
    host::display::draw_string(8, 8, "GRAVITY WELL", 0x506070, 1);
    host::display::present();
}
